import { itemSpec } from './items.js';

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

/**
 * Base premium of the whole policy: the sum of all item base premiums.
 * Components of the same type form a building block when there are exactly
 * BLOCK_SIZE of them, which is billed at the flat block premium instead.
 */
export function policyBasePremium(items: Item[]): number {
  const countByComponentType = new Map<string, number>();
  let total = 0;

  for (const item of items) {
    const spec = itemSpec(item.type);
    if (!spec) continue;
    if (spec.kind === 'component') {
      countByComponentType.set(item.type, (countByComponentType.get(item.type) ?? 0) + 1);
    } else {
      total += spec.basePremium;
    }
  }

  for (const [type, count] of countByComponentType) {
    const unit = itemSpec(type)!.basePremium;
    total += count === BLOCK_SIZE ? BLOCK_PREMIUM : count * unit;
  }

  return total;
}
EOF
