import { Item, policyBasePremium } from './premium.js';

export interface Customer {
  yearsWithMHPCO: number;
}

const PROCESSING_FEE = 5;

/** Rounds in the MHPCO's favour: premiums always go up. */
function roundPremium(amount: number): number {
  return Math.ceil(amount);
}

export function quotePremium(items: Item[], customer: Customer, previousContracts: number): number {
  const base = policyBasePremium(items);
  return roundPremium(base + PROCESSING_FEE);
}
EOF
